INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(41411, 'Jeremiah 48:44', 'Jeremiah', 48, 44, 'هر څوک چې د دهشت نه وتښتى نو په کنده کښې به وغورزيږى. څوک چې د کندې نه راوچت شى نو په دام کښې به ګرفتار شى، ځکه چې زۀ په موآب باندې د سزا وخت راولم، مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_44.mp3', '', 1761754199, 1761754199),
(41412, 'Jeremiah 48:45', 'Jeremiah', 48, 45, 'کوم خلق چې حسبون ته د پناه دپاره وتښتى نو هلته به بې‌وسه ودريږى، ځکه چې د حسبون نه د اور شُغلې راوچتيږى، د بادشاه سيحون د زوړ کور نه به د اور لمبې راوچتيږى. دا اور د موآب تندے سوزوى، او د شور اچوونکو لافوانو کوپړۍ سوزوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_45.mp3', '', 1761754199, 1761754199),
(41413, 'Jeremiah 48:46', 'Jeremiah', 48, 46, 'په تا دې افسوس وى اے موآبه. د کموس بُت عبادت کوونکى تباه شول، ستاسو زامن مُلک بدر شول او ستاسو لوڼه ونيولے شوې او جلاوطن کړے شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_46.mp3', '', 1761754199, 1761754199),
(41414, 'Jeremiah 48:47', 'Jeremiah', 48, 47, 'خو زۀ به بيا موآب په راتلونکى وخت کښې دوباره بحال کړم، مالِک خُدائ فرمائى.“ نو دلته د موآب په حقله د يرمياه نبى پېشګوئې ختمه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah48_verse_47.mp3', '', 1761754199, 1761754199),
(41415, 'Judges 2:1', 'Judges', 2, 1, 'د څښتن فرښته د جلجال څخه بوکیم ته لاړه او اسراییلیانو ته یې وویل: «ما تاسو د مصر څخه راوویستلئ او هغې خاورې ته مې راوستلئ چې ستاسو د نیکونو سره مې د هغې وعده کړې وه. ما وویل چې زه به هېڅکله ستاسو سره خپل لوظ مات نه کړم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_1.mp3', '', 1761754199, 1761754199),
(41416, 'Judges 2:2', 'Judges', 2, 2, 'نو تاسو د دغې خاورې د خلکو سره کوم لوظ ونه کړئ او د هغوی د قربانۍ ځایونه راوغورځوئ. خو څه چې ما درته ویلي وو تاسو هغه ونه کړل. ولې مو داسې وکړل؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_2.mp3', '', 1761754199, 1761754199),
(41417, 'Judges 2:3', 'Judges', 2, 3, 'نو اوس تاسو ته وایم چې زه به دا خلک ستاسو له مخې څخه لېرې نه کړم. هغوی به ستاسو دښمنان وي او د هغوی د خدایانو په عبادت کولو سره به د هغوی په دام کې راګېر اوسئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_3.mp3', '', 1761754199, 1761754199),
(41418, 'Judges 2:4', 'Judges', 2, 4, 'کله چې د څښتن فرښتې دا خبرې وکړې، نو د اسراییلو ټول قوم په لوړ اواز سره وژړل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_4.mp3', '', 1761754199, 1761754199),
(41419, 'Judges 2:5', 'Judges', 2, 5, 'نو په دې خاطر دوی په هغه ځای باندې د بوکیم نوم کېښود او هلته یې څښتن ته قربانۍ وړاندې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_5.mp3', '', 1761754199, 1761754199),
(41420, 'Judges 2:6', 'Judges', 2, 6, 'وروسته له هغې چې یوشع اسراییلیان رخصت کړل، دوی هر یو لاړ چې د خپلې برخې ځمکې ملکیت تر لاسه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_6.mp3', '', 1761754199, 1761754199),
(41421, 'Judges 2:7', 'Judges', 2, 7, 'ترڅو پورې چې یوشع ژوندی ؤ، د اسراییلو خلک څښتن ته وفادار وو او حتی د هغه د مړینې څخه وروسته هم ترڅو پورې چې د قوم هغه سپین ږیري ژوندي وو چې د څښتن هغه لوی لوی کارونه په خپلو سترګو لیدلي وو چې د اسراییلو دپاره یې کړي وو، هغوی څښتن ته وفادار پاتې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_7.mp3', '', 1761754199, 1761754199),
(41422, 'Judges 2:8', 'Judges', 2, 8, 'د څښتن خدمتګار یوشع د نون زوی د یو سلو لسو کالو په عمر مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_8.mp3', '', 1761754199, 1761754199),
(41423, 'Judges 2:9', 'Judges', 2, 9, 'هغه یې په خپله ځمکه کې په تمنه حارس کې چې د افرایم په غرنۍ سیمه کې او د جاعش د غره په شمال کې وه، ښخ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_9.mp3', '', 1761754199, 1761754199),
(41424, 'Judges 2:10', 'Judges', 2, 10, 'کله چې هغه ټول نسل مړ شو او د خپلو نیکونو سره یوځای شو، نو راتلونکي نسل څښتن او د هغه کارونه چې د اسراییلو دپاره یې کړي وو، هېر کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_10.mp3', '', 1761754199, 1761754199),
(41425, 'Judges 2:11', 'Judges', 2, 11, 'د اسراییلو خلکو بیا داسې کارونه وکړل چې د څښتن په نظر کې بد وو او د بعل د بتانو په عبادت یې پیل وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_11.mp3', '', 1761754199, 1761754199),
(41426, 'Judges 2:12', 'Judges', 2, 12, 'هغوی د هغه څښتن عبادت کول پرېښودل چې د دوی د نیکونو خدای ؤ او دوی یې د مصر څخه راویستلي وو. دوی د خپل شاوخوا خلکو خدایانو ته عبادت کاوه. هغوی ته یې سجده کوله او څښتن یې په قهر کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_12.mp3', '', 1761754199, 1761754199),
(41427, 'Judges 2:13', 'Judges', 2, 13, 'هغوی څښتن پرېښود او د بعل او عشتاروت د بتانو عبادت یې غوره کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_13.mp3', '', 1761754199, 1761754199),
(41428, 'Judges 2:14', 'Judges', 2, 14, 'نو څښتن په اسراییلو باندې ډېر په قهر شو او هغوی یې یرغلګرو ته په لاس ورکړل او یرغلګرو هغوی لوټ کړل. څښتن دوی خپلو دښمنانو ته تسلیم کړل او اسراییلیانو نور نه شو کولای چې د هغوی په وړاندې مقاومت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_14.mp3', '', 1761754199, 1761754199),
(41429, 'Judges 2:15', 'Judges', 2, 15, 'هر ځل چې اسراییلیان د جګړې دپاره وتل، څښتن د هغوی په خلاف عمل کاوه چې ماتې وخوري، ځکه چې هغه دوی ته قسم خوړلی ؤ چې دا کار به کوي. هغوی په لوی مصیبت اخته شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_15.mp3', '', 1761754199, 1761754199),
(41430, 'Judges 2:16', 'Judges', 2, 16, 'بیا څښتن اسراییلیانو ته ځانګړي مشران چې د قاضیانو په نوم هم یادېدل ورکړل چې هغوی د یرغلګرو څخه وژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_16.mp3', '', 1761754199, 1761754199),
(41431, 'Judges 2:17', 'Judges', 2, 17, 'خو اسراییلیانو خپلو مشرانو ته غوږ نه نیوه. اسراییلو د څښتن سره بې وفایي کوله او د نورو خدایانو عبادت به یې کاوه. د هغوی پلرونو به د څښتن حکمونو ته غاړه ایښودله، خو نوي نسل زر دا کار پرېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_17.mp3', '', 1761754199, 1761754199),
(41432, 'Judges 2:18', 'Judges', 2, 18, 'هرکله چې څښتن اسراییلو ته یو مشر ورکاوه، څښتن به د هغه مشر سره مرسته کوله او ترڅو پورې به چې هغه مشر ژوندی ؤ، خلک به یې د خپلو دښمنانو څخه ژغورل. څښتن په هغوی باندې رحم کاوه، ځکه چې هغوی به د ظلم او کړېدلو د لاسه فریاد کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_18.mp3', '', 1761754199, 1761754199),
(41433, 'Judges 2:19', 'Judges', 2, 19, 'خو کله به چې هغه مشر مړ شو، خلک به بېرته خپلو بدو لارو ته راګرځېدل او د خپلو نیکونو څخه به یې نور هم زیات فساد کاوه. د نورو خدایانو پیروي او عبادت به یې کاوه. دوی به خپل بد عملونه او سرزوري نه پرېښودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_19.mp3', '', 1761754199, 1761754199),
(41434, 'Judges 2:20', 'Judges', 2, 20, 'نو بیا څښتن په اسراییلو باندې ډېر په قهر شو او ویې ویل: «په دې خاطر چې دې قوم هغه لوظ مات کړی دی چې د هغوی د نیکونو سره مې کړی ؤ او زما حکم یې نه دی منلی،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_20.mp3', '', 1761754199, 1761754199),
(41435, 'Judges 2:21', 'Judges', 2, 21, 'نو زه به نور هغه قومونه چې د یوشع د مړینې څخه وروسته پاتې شوي وو، ونه شړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_21.mp3', '', 1761754199, 1761754199),
(41436, 'Judges 2:22', 'Judges', 2, 22, 'زه به د هغوی څخه کار واخلم، ترڅو دا معلومه شي چې دا اسراییلیان د خپلو پلرونو په شان زما په لاره باندې روان دي او که نه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_22.mp3', '', 1761754199, 1761754199),
(41437, 'Judges 2:23', 'Judges', 2, 23, 'نو څښتن هغه قومونه پرېښودل چې په هغې خاوره کې پاتې شي. هغه یوشع ته په هغوی باندې بری ورنه کړ او نه یې د یوشع د مړینې څخه وروسته هغوی زر وشړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges2_verse_23.mp3', '', 1761754199, 1761754199),
(41438, 'Jeremiah 9:1', 'Jeremiah', 9, 1, '”کاش چې زما سر د اوبو چينه وے، او زما سترګې د اوښکو چينې وے، ترڅو چې ما شپه او ورځ د خپلو خلقو په قتلولو ژړا انګولا کولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_1.mp3', '', 1761754199, 1761754199),
(41439, 'Jeremiah 9:2', 'Jeremiah', 9, 2, 'کاش چې په صحرا کښې زما يو سرائى وے، چرته چې ما خپل خلق پرېښودى وے او هلته د دوئ نه لرې اوسېدلم. ځکه چې دوئ ټول د خُدائ پاک سره بې‌وفائى کوى، او د بې‌ايمانانو يوه ډله ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_2.mp3', '', 1761754199, 1761754199),
(41440, 'Jeremiah 9:3', 'Jeremiah', 9, 3, 'مالِک خُدائ فرمائى، ”هغوئ د خپلو ژبو نه ليندې جوړې کړې دى او د دروغو غشى هر وخت ورَوى. د دې مُلک په ديانتدارۍ کښې صداقت نشته، هغوئ د يوې ګناه دپاسه بله ګناه کوى، هغوئ ما نۀ پېژنى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_3.mp3', '', 1761754199, 1761754199),
(41441, 'Jeremiah 9:4', 'Jeremiah', 9, 4, 'تاسو هر يو په خپل دوست نظر ساتئ او په خپل ورور هم اعتبار مۀ کوئ. ځکه چې هر يو ورور ستاسو دوکه مار دے، او هر يو دوست غېبت کوونکے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_4.mp3', '', 1761754199, 1761754199),
(41442, 'Jeremiah 9:5', 'Jeremiah', 9, 5, 'هر يو دوست بل دوست سره دوکه کوى، او يو هم رښتيا خبره نۀ کوى، هغوئ خپلو ژبو ته د دروغو وئيلو تعليم ورکړے دے، او په ګناه کولو سره خپل ځان ستړے کوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_5.mp3', '', 1761754199, 1761754199),
(41443, 'Jeremiah 9:6', 'Jeremiah', 9, 6, 'مالِک خُدائ فرمائى چې، ”تاسو د دوکه مارانو او د دروغژنو په مينځ کښې اوسېږئ، او د خپلو دوکه کولو په وجه دوئ نۀ غواړى چې ما وپېژنى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_6.mp3', '', 1761754199, 1761754199),
(41444, 'Jeremiah 9:7', 'Jeremiah', 9, 7, 'نو په دې وجه مالِک خُدائ ربُ الافواج فرمائى، ”زۀ به دوئ لکه د کچه سپينو زرو په شان د اور بټۍ کښې واچوم، صفا به يې کړم او وبه يې آزمايمه، زۀ نور د دې ګناه ګار قوم سره څۀ وکړم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_7.mp3', '', 1761754199, 1761754199),
(41445, 'Jeremiah 9:8', 'Jeremiah', 9, 8, 'د هغوئ ژبې لکه د زهريله غشو په شان دى، او هغوئ همېشه دروغ وائى. او هغوئ په خولۀ د خپل ګاونډى سره خوږه لهجه کوى، خو په حقيقت کښې د هغوئ دپاره بدې منصوبې جوړوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_8.mp3', '', 1761754199, 1761754199),
(41446, 'Jeremiah 9:9', 'Jeremiah', 9, 9, 'مالِک خُدائ فرمائى چې، ”آيا زۀ دوئ ته د دې بدو کارونو سزا ورنۀ کړم څۀ؟ آيا د داسې قوم نه بدله خپله وانۀ خلم څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_9.mp3', '', 1761754199, 1761754199),
(41447, 'Jeremiah 9:10', 'Jeremiah', 9, 10, 'زۀ به د غرونو دپاره ژړا وکړم، او د بيابان د څرن په ځايونو به د غم سندرې ووايم. ځکه چې څوک هم په هغې تګ راتګ نۀ کوى، او ټول شينکے سوزېدلے او اوچ شوے دے او د رمو آوازونه په کښې نۀ اورېدلے کيږى. د هوا مارغان او ځنګلى ځناور ټول ترې نه تښتېدلى دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_10.mp3', '', 1761754199, 1761754199),
(41448, 'Jeremiah 9:11', 'Jeremiah', 9, 11, 'مالِک خُدائ فرمائى چې، ”زۀ به د يروشلم نه د خاورو ډېرے، او د ګيدړانو غار جوړ کړم. او د يهوداه ښارونه به وران او خاموشه کړم، نو هيڅوک به هلته کښې نۀ اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_11.mp3', '', 1761754199, 1761754199),
(41449, 'Jeremiah 9:12', 'Jeremiah', 9, 12, 'نو بيا به څوک دومره هوښيار وى چې په دې ټوله موضوع پوهه شى؟ چا ته د مالِک خُدائ نه دومره هدايت مِلاو شوے دے چې دا بيان کړى چې دا مُلک ولې وران شوے دے؟ دا ولې په ريګستان بدل شوے دے، او دومره ولې وران او خراب شوے دے چې هيڅوک هم پرې تېرېدلے نۀ شى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_12.mp3', '', 1761754199, 1761754199),
(41450, 'Jeremiah 9:13', 'Jeremiah', 9, 13, 'مالِک خُدائ وفرمائيل چې، ”دا ځکه چې هغوئ زما شريعت هېر کړو کوم تعليم چې ما هغوئ ته وړاندې کړے وو، نۀ هغوئ زما کلام ومنلو او نۀ يې د هغې پيروى وکړه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_13.mp3', '', 1761754199, 1761754199),
(41451, 'Jeremiah 9:14', 'Jeremiah', 9, 14, 'بلکې د دې په ځائ هغوئ د خپل سرکشه زړونو پيروى وکړه، او هغوئ د بعل د بُت پيروى وکړه لکه څنګه چې د هغوئ پلار نيکۀ ورته د عبادت کولو تعليم ورکړے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_14.mp3', '', 1761754199, 1761754199),
(41452, 'Jeremiah 9:15', 'Jeremiah', 9, 15, 'نو ځکه، مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، ګورئ، زۀ به هغوئ ته د خوړلو دپاره ګنډير ورکړم او د څښلو دپاره به زهريله اوبۀ ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_15.mp3', '', 1761754199, 1761754199),
(41453, 'Jeremiah 9:16', 'Jeremiah', 9, 16, 'زۀ به هغوئ په داسې قومونو کښې خوارۀ وارۀ کړم چې نۀ به يې دوئ او نۀ به يې د دوئ پلار نيکۀ پېژنى، او زۀ به په دوئ جنګ راولم ترڅو چې يې هلاک کړى نۀ وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_16.mp3', '', 1761754199, 1761754199),
(41454, 'Jeremiah 9:17', 'Jeremiah', 9, 17, 'مالِک خُدائ ربُ الافواج دا فرمائى چې، ”هغه څۀ چې کېدونکى دى په هغې غور وکړئ. سندرې ويونکې او ماتم کوونکې ښځې راوغواړئ چې راشى، او هغه ښځې راوغواړئ چې په مړى په ژړا کولو کښې ماهرې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_17.mp3', '', 1761754199, 1761754199),
(41455, 'Jeremiah 9:18', 'Jeremiah', 9, 18, 'لاړ شئ او هغوئ زر راولئ چې په مونږ باندې دومره ژړا او سندرې ووائى ترڅو زمونږ سترګې د اوښکو نه ډکې شى، او زمونږ د بڼو نه اوښکې روانې شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_18.mp3', '', 1761754199, 1761754199),
(41456, 'Jeremiah 9:19', 'Jeremiah', 9, 19, 'د صيون نه د ژړا آوازونه اورېدلے کيږى چې وائى، ”واى، واى، مونږه څنګه تباه شُو او په شرمونو وشرمېدو. مونږ مُلک پرېښودو ته مجبوره شوى يُو، ځکه چې زمونږ کورونه تباه شوى دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_19.mp3', '', 1761754199, 1761754199),
(41457, 'Jeremiah 9:20', 'Jeremiah', 9, 20, 'اے ښځو، د مالِک خُدائ کلام ته غوږ ونيسئ، او د هغۀ د خولې هرې خبرې ته غوږ ونيسئ. خپلو لوڼو ته د سندرو او ماتم کولو تعليم ورکړئ، او يو بل ته په خپلو کښې د ماتم کولو تعليم ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_20.mp3', '', 1761754199, 1761754199),
(41458, 'Jeremiah 9:21', 'Jeremiah', 9, 21, 'ځکه چې مرګ زمونږ کور ته په کړکو راننوتے دے او زمونږ قلعو ته رادننه شوے دے، هغه اوس ماشومان د کوڅو نه او ځوانان د بازارونو او چوکونو نه راټولوى او تېروى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_21.mp3', '', 1761754199, 1761754199),
(41459, 'Jeremiah 9:22', 'Jeremiah', 9, 22, 'مالِک خُدائ فرمائى، ”خلقو ته ووايه چې د مړو لاشونه به په پټو کښې لکه د ډېران د سرې پراتۀ وى، او لکه د غنمو وږې په شان د لَوګرى شا ته اخوا ديخوا پراتۀ وى دغه شان به مړى هرې خوا ته پراتۀ وى او د راټولولو به يې څوک نۀ وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_22.mp3', '', 1761754199, 1761754199),
(41460, 'Jeremiah 9:23', 'Jeremiah', 9, 23, 'مالِک خُدائ فرمائى، ”هوښيار دې په خپله هوښيارتيا فخر ونۀ کړى، نۀ دې زورَور په خپل زور باندې او نۀ دې دولتمند په خپل دولت باندې فخر وکړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_23.mp3', '', 1761754199, 1761754199),
(41461, 'Jeremiah 9:24', 'Jeremiah', 9, 24, 'مالِک خُدائ فرمائى چې، ”کۀ څوک فخر کول غواړى نو هغه دې په دې خبره فخر وکړى چې دوئ ما پېژنى او په دې پوهيږى چې زۀ هغه مالِک خُدائ يم چې په زمکه باندې نۀ ختمېدونکې مينه، عدل و اِنصاف او صداقت راولم. ځکه چې په دې څيزونو کښې زما خوشحالى ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_24.mp3', '', 1761754199, 1761754199),
(41462, 'Jeremiah 9:25', 'Jeremiah', 9, 25, 'مالِک خُدائ فرمائى، ”هغه ورځې راروانې دى چې، زۀ به ټولو هغه خلقو ته سزا ورکړم څوک چې صرف جسمانى سنت شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_25.mp3', '', 1761754199, 1761754199),
(41463, 'Jeremiah 9:26', 'Jeremiah', 9, 26, 'زۀ به مِصر، ادوم، عمون، موآب او هغوئ ته څوک چې په دشتو او ميرو کښې اوسيږى سزا ورکړم، او ورسره به بنى اِسرائيل ته هم سزا ورکړم. ځکه چې د ټولو بُت پرستو قومونو په شان، د دوئ زړونه هم مالِک خُدائ ته وقف نۀ دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah9_verse_26.mp3', '', 1761754199, 1761754199),
(41464, 'Exodus 14:1', 'Exodus', 14, 1, 'بیا څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_1.mp3', '', 1761754199, 1761754199),
(41465, 'Exodus 14:2', 'Exodus', 14, 2, '«اسراییلیانو ته ووایه چې بېرته راوګرځي او فم الحیروت ته مخامخ چې د مجدل او د سرې بحیرې ترمنځ او بعل صفون ته نژدې دی خېمې ودروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_2.mp3', '', 1761754199, 1761754199),
(41466, 'Exodus 14:3', 'Exodus', 14, 3, 'فرعون به فکر وکړي چې اسراییلیان به په وطن کې سرګردانه ګرځي او د وارخطایۍ په حالت کې په دښته کې بند پاتې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_3.mp3', '', 1761754199, 1761754199),
(41467, 'Exodus 14:4', 'Exodus', 14, 4, 'زه به د فرعون زړه سخت کړم او هغه به دوی تعقیب کړي. خو د فرعون او د هغه په لښکرو باندې به زما بریالیتوب زما د جلال سبب شي. بیا به مصریان پوه شي چې زه څښتن یم.» لکه څنګه چې هغوی ته ویل شوي وو، اسراییلیانو هماغسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_4.mp3', '', 1761754199, 1761754199),
(41468, 'Exodus 14:5', 'Exodus', 14, 5, 'کله چې فرعون خبر شو چې د اسراییلو قوم تښتېدلی دی، هغه او د هغه درباریانو د هغوی په هکله خپله پرېکړه بدله کړه او ویې ویل: «مونږ څه وکړل؟ مونږ اسراییلیان پرېښودل چې وتښتي او هغوی چې زمونږ غلامان وو له لاسه مو ورکړل!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_5.mp3', '', 1761754199, 1761754199),
(41469, 'Exodus 14:6', 'Exodus', 14, 6, 'فرعون خپلې جنګي ګاډۍ ګانې او لښکرې تیارې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_6.mp3', '', 1761754199, 1761754199),
(41470, 'Exodus 14:7', 'Exodus', 14, 7, 'هغه د ځان سره شپږ سوه ښې ښې جنګي ګاډۍ ګانې د مصر د نورو ټولو جنګي ګاډیو سره چې د هر یو سره خپل خپل قوماندان ؤ، یووړلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_7.mp3', '', 1761754199, 1761754199),
(41471, 'Exodus 14:8', 'Exodus', 14, 8, 'څښتن د فرعون زړه سخت کړ، نو هغه د اسراییلیانو پسې چې په زوړورتیا سره د مصر څخه ووتل، روان شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_8.mp3', '', 1761754199, 1761754199),
(41472, 'Exodus 14:9', 'Exodus', 14, 9, 'د مصریانو لښکرې، د فرعون ټول اسونه، جنګي ګاډۍ ګانې، اس سواران او لښکرې د اسراییلیانو پسې روان شول او د هغوی څخه مخکې شول، چېرته چې هغوی د بحیرې سره چې فم الحیروت او بعل صفون ته نژدې ؤ، خېمې ودرولې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_9.mp3', '', 1761754199, 1761754199),
(41473, 'Exodus 14:10', 'Exodus', 14, 10, 'څنګه چې فرعون نژدې شو، اسراییلیانو سترګې پورته کړې او ویې لیدل چې مصریان هغوی پسې راروان دي. هغوی ډېر ووېرېدل او څښتن ته یې فریاد وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_10.mp3', '', 1761754199, 1761754199),
(41474, 'Exodus 14:11', 'Exodus', 14, 11, 'هغوی موسی ته وویل: «ایا په مصر کې قبرونه نه وو چې تا دلته دښتې ته راوستلو چې مړه شو؟ ګوره تا زمونږ سره څه وکړل چې د مصر څخه دې راوویستلو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_11.mp3', '', 1761754199, 1761754199),
(41475, 'Exodus 14:12', 'Exodus', 14, 12, 'ایا تاته مونږ په مصر کې ونه ویل چې مونږ پرېږده چې د مصریانو غلامان اوسو؟ مونږ ته په دښته کې د مړه کېدلو څخه د مصریانو غلامي ښه ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_12.mp3', '', 1761754199, 1761754199),
(41476, 'Exodus 14:13', 'Exodus', 14, 13, 'موسی په ځواب کې وویل: «مه وېرېږئ! په خپل ځای کې ودرېږئ. تاسو به ووینئ چې څښتن نن تاسو ته څنګه خلاصون درکوي. کوم مصریان چې نن یې وینئ، هغه به بیا هېڅکله ونه وینئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_13.mp3', '', 1761754199, 1761754199),
(41477, 'Exodus 14:14', 'Exodus', 14, 14, 'تاسو غلي اوسئ، څښتن به ستاسو دپاره جګړه وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_14.mp3', '', 1761754199, 1761754199),
(41478, 'Exodus 14:15', 'Exodus', 14, 15, 'څښتن موسی ته وویل: «ته ولې ماته د مرستې په خاطر فریاد کوې؟ خلکو ته ووایه چې وړاندې لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_15.mp3', '', 1761754199, 1761754199),
(41479, 'Exodus 14:16', 'Exodus', 14, 16, 'خپله امسا پورته کړه او د بحیرې خواته یې ونیسه. اوبه به بېلې شي او اسراییلیان به وکولای شي چې په بحیره کې په وچه ځمکه باندې تېر شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_16.mp3', '', 1761754199, 1761754199),
(41480, 'Exodus 14:17', 'Exodus', 14, 17, 'زه به د مصریانو زړونه سخت کړم چې هغوی تاسو پسې درشي او زه به په فرعون، د هغه په لښکرو او جنګي ګاډیو او د هغو په چلوونکو باندې د بریالیتوب په سبب جلال ومومم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_17.mp3', '', 1761754199, 1761754199),
(41481, 'Exodus 14:18', 'Exodus', 14, 18, 'کله چې زه د فرعون، د هغه جنګي ګاډیو او اس سوارانو ته ماتې ورکړم او خپل جلال ښکاره کړم، مصریان به پوه شي چې زه څښتن یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_18.mp3', '', 1761754199, 1761754199),
(41482, 'Exodus 14:19', 'Exodus', 14, 19, 'د خدای فرښته چې د اسراییلو د لښکرو په مخکې روانه وه، شاته لاړه. هغه د ستنې په شان ورېځ هم د هغوی شاته حرکت وکړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_19.mp3', '', 1761754199, 1761754199),
(41483, 'Exodus 14:20', 'Exodus', 14, 20, 'او هغه د مصریانو او د اسراییلیانو په منځ کې شوه. د شپې په دوران کې ورېځې په مصریانو باندې تیاره راوستله، خو د اسراییلو په قوم یې رڼا راوستله. نو لښکرې په ټوله شپه کې یو بل ته نژدې نه شوې ورتللی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_20.mp3', '', 1761754199, 1761754199),
(41484, 'Exodus 14:21', 'Exodus', 14, 21, 'موسی د بحیرې دپاسه خپل لاس ونیوه او څښتن په قوي ختیځ باد باندې د بحیرې اوبه شاته یووړلې. دا باد ټوله شپه ولګېده او بحیره یې په وچه ځمکه بدله کړه. اوبه بېلې شوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_21.mp3', '', 1761754199, 1761754199),
(41485, 'Exodus 14:22', 'Exodus', 14, 22, 'او اسراییلیان په بحیره کې په وچه ځمکه باندې تېر شول او دواړو خواو ته د اوبو دېوالونه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_22.mp3', '', 1761754199, 1761754199),
(41486, 'Exodus 14:23', 'Exodus', 14, 23, 'مصریان د خپلو ټولو اسونو، جنګي ګاډیو او د اس سوارانو سره هغوی تعقیب کړل او په بحیره کې ورپسې روان شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_23.mp3', '', 1761754199, 1761754199),
(41487, 'Exodus 14:24', 'Exodus', 14, 24, 'د سهار د رڼا نه مخکې، څښتن د اور او ورېځې له منځ څخه د مصریانو لښکرو ته وکتل او هغوی یې وارخطا کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_24.mp3', '', 1761754199, 1761754199),
(41488, 'Exodus 14:25', 'Exodus', 14, 25, 'څښتن د هغوی د ګاډیو ارابې له کاره وغورځولې، نو هغه په سختۍ سره چلېدلې. او مصریانو وویل: «راځئ چې له دې ځای څخه وتښتو، ځکه چې څښتن زمونږ په خلاف د اسراییلیانو دپاره جنګیږي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_25.mp3', '', 1761754199, 1761754199),
(41489, 'Exodus 14:26', 'Exodus', 14, 26, 'بیا څښتن موسی ته وویل: «خپل لاس دې د بحیرې ته اوږد کړه. نو اوبه به بېرته په مصریانو، د هغوی په جنګي ګاډیو او اس سوارانو باندې راشي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_26.mp3', '', 1761754199, 1761754199),
(41490, 'Exodus 14:27', 'Exodus', 14, 27, 'نو موسی خپل لاس د بحیرې خواته اوږد کړ او د سهار وختي اوبه خپل لومړني حالت ته راوګرځېدلې. مصریانو هڅه وکړه چې وتښتي، خو څښتن بحیرې ته وروغورځول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_27.mp3', '', 1761754199, 1761754199),
(41491, 'Exodus 14:28', 'Exodus', 14, 28, 'اوبه راوګرځېدلې او جنګي ګاډۍ ګانې، اس سواران او ټولې مصري لښکرې یې چې په بحیره کې د اسراییلیانو پسې وې، ډوب کړل او یو هم ژوندی پاتې نه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_28.mp3', '', 1761754199, 1761754199),
(41492, 'Exodus 14:29', 'Exodus', 14, 29, 'خو اسراییلیان په بحیره کې په وچه ځمکه باندې چې اوبه د هغې دواړو خواو ته لکه د دېوالونو په شان ولاړې وې، تېر شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_29.mp3', '', 1761754199, 1761754199),
(41493, 'Exodus 14:30', 'Exodus', 14, 30, 'په هغه ورځ څښتن اسراییلیان د مصریانو څخه وژغورل او اسراییلیانو هغوی ولیدل چې د بحیرې په غاړه مړه پراته وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_30.mp3', '', 1761754199, 1761754199),
(41494, 'Exodus 14:31', 'Exodus', 14, 31, 'کله چې اسراییلیانو د څښتن لوی قدرت چې هغه مصریانو ته وښوده ولیده، نو هغوی د څښتن څخه ووېرېدل او په هغه او د هغه په خدمتګار موسی باندې یې ایمان راوړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus14_verse_31.mp3', '', 1761754199, 1761754199),
(41495, 'Exodus 23:1', 'Exodus', 23, 1, 'د دروغو خبر مه خپروئ. د دروغو په شاهدۍ ورکولو سره د بدکاره سړي سره مرسته مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_1.mp3', '', 1761754199, 1761754199),
(41496, 'Exodus 23:2', 'Exodus', 23, 2, 'په بد کار کې د اکثریت څخه پیروي مه کوئ. کله چې تاسو په یوه دعوه کې شاهدي ورکوئ، د اکثریت څخه د طرفدارۍ په کولو سره عدالت تر پښو لاندې مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_2.mp3', '', 1761754199, 1761754199),
(41497, 'Exodus 23:3', 'Exodus', 23, 3, 'د یو غریب سړي په محاکمه کې په دې خاطر چې هغه غریب دی، د هغه طرفداري مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_3.mp3', '', 1761754199, 1761754199),
(41498, 'Exodus 23:4', 'Exodus', 23, 4, 'که چېرې تاسو ناڅاپه د خپل دښمن غویی یا خر ووینئ چې لار یې غلطه کړې ده، هغه بېرته ورولئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_4.mp3', '', 1761754199, 1761754199),
(41499, 'Exodus 23:5', 'Exodus', 23, 5, 'که چېرې تاسو ولیدل چې ستاسو د دښمن خر د بار لاندې پرېوتی دی، هغه هلته مه پرېږدئ، د هغه سره مرسته وکړئ چې خر یې بېرته پاڅیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_5.mp3', '', 1761754199, 1761754199),
(41500, 'Exodus 23:6', 'Exodus', 23, 6, 'په محکمه کې د غریب سره بې انصافي مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_6.mp3', '', 1761754199, 1761754199),
(41501, 'Exodus 23:7', 'Exodus', 23, 7, 'په دروغو تهمت مه لګوئ او د یو بې ګناه یا صادق سړي د مړینې سبب کېږئ مه. ځکه چې زه به ګناهکار ونه بخښم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_7.mp3', '', 1761754199, 1761754199),
(41502, 'Exodus 23:8', 'Exodus', 23, 8, 'رشوت مه اخلئ، ځکه چې رشوت بینا خلک ړندوي او د بې ګناه خلکو حق ورباندې تر پښو لاندې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_8.mp3', '', 1761754199, 1761754199),
(41503, 'Exodus 23:9', 'Exodus', 23, 9, 'په یو مسافر سړي باندې تېری مه کوئ. ځکه چې تاسو خپله په مصر کې مسافران وئ او د مسافرانو د حال څخه خبر یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_9.mp3', '', 1761754199, 1761754199),
(41504, 'Exodus 23:10', 'Exodus', 23, 10, 'تاسو باید شپږ کاله خپلې ځمکې وکرئ او حاصل یې ورېبئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_10.mp3', '', 1761754199, 1761754199),
(41505, 'Exodus 23:11', 'Exodus', 23, 11, 'خو په اووم کال هغه ځمکه شاړه پرېږدئ او څه شی چې په کې شنه شوي وي، هغه ورڅخه مه رېبئ. څه چې په کې پاتې وي هغه به غریبان خلک او وحشي حیوانات وخوري. خپل د انګورو باغونو او د زیتونو د ونو د باغونو سره همداسې کار وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_11.mp3', '', 1761754199, 1761754199),
(41506, 'Exodus 23:12', 'Exodus', 23, 12, 'په هفته کې شپږ ورځې خپل کار وکړئ، خو په اوومه ورځ کار مه کوئ، ترڅو ستاسو غلامان او پردي خلک چې ستاسو دپاره کار کوي او حتی ستاسو حیوانات هم وکولای شي ارام وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_12.mp3', '', 1761754199, 1761754199),
(41507, 'Exodus 23:13', 'Exodus', 23, 13, 'هرڅه چې ما څښتن درته ویلي دي، په هغو باندې عمل کوئ. د نورو خدایانو په نوم دعا مه کوئ، حتی د هغوی نومونه هم په ژبه مه اخلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_13.mp3', '', 1761754199, 1761754199),
(41508, 'Exodus 23:14', 'Exodus', 23, 14, 'زما د درناوي په خاطر په کال کې درې ځله اخترونه لمانځئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_14.mp3', '', 1761754199, 1761754199),
(41509, 'Exodus 23:15', 'Exodus', 23, 15, 'لومړی د فطیرې ډوډۍ اختر. لکه څنګه چې ما درته حکم کړی دی اووه ورځې فطیره ډوډۍ وخورئ. دا کار د ابیب په میاشت کې وکړئ، ځکه چې په دې میاشت کې تاسو له مصر څخه راووتلئ. په دې اختر کې دې هېڅوک زما حضور ته خالي لاس نه راځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_15.mp3', '', 1761754199, 1761754199),
(41510, 'Exodus 23:16', 'Exodus', 23, 16, 'تاسو د لو کولو اختر د خپلو لومړنیو حاصلاتو سره چې په خپلو پټیو کې مو کرلي دي، ولمانځئ. د کال په اخر کې د حاصل د راټولولو اختر ولمانځئ، یعنې کله چې تاسو د پټیو څخه حاصل راټولوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_16.mp3', '', 1761754199, 1761754199);